function linking(id, level, premises, conclusion, choices, correctChoiceId, explanation, groupTags) {
  return {
    id,
    mode: "linking",
    level,
    premises,
    conclusion,
    prompt: "What's the missing link?",
    choices: choices.map((text, index) => ({ id: "ABCDE"[index], text })),
    correctChoiceId,
    explanation,
    groupTags
  };
}
